/* Textured mechanical carrier derived from the new side-profile mould. Geometry, pigment and motion are shared by the photographic and orbit cameras. */
window.CarrierMeshData=function(){const b=s=>Uint8Array.from(atob(s),x=>x.charCodeAt(0));return {pos:Float32Array.from(new Int16Array(b('').buffer),v=>v/25000),uv:Float32Array.from(new Uint16Array(b('').buffer),v=>v/65535),idx:new Uint16Array(b('').buffer),weights:Float32Array.from(b(''),v=>v/255),phase:Float32Array.from(b(''),v=>v/255*6.283185)}};
